# ============================================================================
# check_svg_snapshots.sh — BLUE20 layer 3 (SVG 全量快照再生门禁)
# ============================================================================
# The rule this guards (BLUE20 #106):
#
#   **A snapshot that is not regenerated by a gate is a picture someone looked at
#   once, not an artifact that catches a regression.**
#
# Why the snapshots are committed and re-generated here
# -----------------------------------------------------
# Layers 1 and 2 are machine judgements; they cannot see "this control looks wrong".
# The committed SVGs under `snapshots/svg/` are the human-reviewable half — a dark/light
# pair per control, plus a pair for each companion pairing and the icon sheets. That value
# depends entirely on the files being *current*: if a control's drawing changes and the
# snapshot does not, the next reviewer approves a picture of something that no longer
# exists.
#
# So this gate regenerates the whole set into a scratch directory and requires a
# byte-for-byte match. It is the same shape as `check_generated_sources.sh` and
# `check_abi.sh`: the generator is the source of truth, the committed file is a
# build artifact that must equal its producer's output.
#
# What it asserts
# ---------------
#   [1] the count is the parent factory's own control count, dark + light per control, plus the two icon
#       sheets (BLUE25 ICON-7) and every companion pairing's dark/light file, which are
#       counted separately
#   [2] every file is non-empty and contains at least one drawing element
#   [3] regeneration matches the committed files byte for byte
#   [4] the two appearances actually differ for every control
#   [5] the committed gallery index matches the snapshot set
#
# Step [4] is the one that would have caught the defect this layer first shipped
# with: before `theme::apply_theme_to_widget` existed, every `.svg` and its
# `.light.svg` were byte-identical apart from a comment — the snapshots existed,
# listed correctly, and showed nothing about the theme.
#
# Exit 0 = snapshots current and complete. Exit 1 = a finding.
# ============================================================================

set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"

. "$ROOT_DIR/tools/lib_timeout.sh"
. "$ROOT_DIR/tools/lib_cargo_cache.sh"
. "$ROOT_DIR/tools/lib_python.sh"

STEP_BUDGET="${RW_GATE_TIMEOUT:-900}"
SNAPSHOT_DIR="snapshots/svg"
# A scratch tree, never in the repo: a failure must not leave the working tree dirty for
# the next gate, and a partial regeneration must not be mistaken for a good one.
SCRATCH="$(mktemp -d)"
trap 'rm -rf "$SCRATCH"' EXIT

echo "[1/5] capture the committed state, then regenerate into a scratch tree"
# The committed files are hashed BEFORE anything regenerates. Comparing `git diff` AFTER
# the exporter has run in place cannot detect a changed snapshot: the exporter overwrites
# the change and the tree looks clean again. That made the first version of this gate pass
# when a committed byte was edited by hand — the exact silent-pass defect (BLUE20 #107,
# and the round-58 §3.2.1 "window at (0,0)" false pass). Hashing first is what makes the
# comparison meaningful.
BEFORE="$SCRATCH/before.sha"
if command -v sha256sum >/dev/null 2>&1; then
    find "$SNAPSHOT_DIR" -maxdepth 1 -name '*.svg' -print0 | sort -z | xargs -0 sha256sum > "$BEFORE" 2>/dev/null || true
else
    # Windows hosts frequently lack `sha256sum`; `shasum` is the common fallback and
    # `certutil` is the last resort. A gate that cannot hash must say so rather than
    # silently compare nothing.
    (cd "$SNAPSHOT_DIR" && find . -maxdepth 1 -name '*.svg' | sort | xargs shasum -a 256) > "$BEFORE" 2>/dev/null || {
        echo "  FAIL  no SHA-256 tool available, so the snapshot comparison cannot run"
        exit 1
    }
fi
if [[ ! -s "$BEFORE" ]]; then
    echo "  FAIL  hashing the committed snapshots produced nothing"
    exit 1
fi

echo "[2/5] regenerate every snapshot in place"
# `_DEFAULT_FEATURES`, not `desktop`: the snapshot set is the picture of what a plain
# `cargo build` produces, and `default = ["desktop", "icons"]`. Rendering it from the `desktop`
# *profile* alone would leave two of those controls (`icon` among them) showing the shapes a
# build without the icon data draws — a picture that is current for nobody, since no caller gets
# `desktop` by itself without also asking for it. The gate's own contract is "what a reviewer
# sees is what ships", so the exporter runs what ships.
DEFAULT_FEATURES="$("$PYTHON" tools/svg_snapshot_check.py default-features)"
echo "        exporting with --features $DEFAULT_FEATURES (the manifest's \`default\`)"
if ! rw_cargo_cached "$STEP_BUDGET" run \
    --no-default-features --features "$DEFAULT_FEATURES" \
    --example export_control_svgs > "$SCRATCH/export.log" 2>&1; then
    echo "  FAIL  the SVG exporter did not run"
    sed -n '1,60p' "$SCRATCH/export.log"
    exit 1
fi
grep -E '^(wrote|checked)' "$SCRATCH/export.log" || true

# BLUE25 ICON-7 — the icon sheets are the same kind of artifact (generated, committed,
# diffable), so they are regenerated by the same gate and compared the same way. They are
# gated on the opt-in `icons` feature, which is why they are a second command: the control
# set must keep regenerating *without* the icon payload, and only the sheet needs it.
#
# The exporter is a no-op when the feature is off, so a build without `icons` leaves the
# committed sheets untouched and step 3 compares them with themselves — which is the
# honest outcome: this gate does not own their *content* on such a build, only the
# requirement that they are current when the data is present.
if ! rw_cargo_cached "$STEP_BUDGET" run \
    --no-default-features --features desktop,icons \
    --example export_icon_sheet > "$SCRATCH/icon_sheet.log" 2>&1; then
    echo "  FAIL  the icon-sheet exporter did not run"
    sed -n '1,60p' "$SCRATCH/icon_sheet.log"
    exit 1
fi
grep -E '^wrote' "$SCRATCH/icon_sheet.log" || true

AFTER="$SCRATCH/after.sha"
if command -v sha256sum >/dev/null 2>&1; then
    find "$SNAPSHOT_DIR" -maxdepth 1 -name '*.svg' -print0 | sort -z | xargs -0 sha256sum > "$AFTER" 2>/dev/null || true
else
    (cd "$SNAPSHOT_DIR" && find . -maxdepth 1 -name '*.svg' | sort | xargs shasum -a 256) > "$AFTER" 2>/dev/null || true
fi

if ! diff -q "$BEFORE" "$AFTER" > /dev/null; then
    echo "  FAIL  the committed snapshots differ from a fresh export (byte-for-byte):"
    diff "$BEFORE" "$AFTER" | sed -n '1,40p'
    echo "  Regenerate with:"
    echo "    cargo run --no-default-features --features \"desktop,code-editor,markdown-editor,builtin-languages\" --example export_control_svgs"
    exit 1
fi
echo "  PASS  regeneration reproduces every committed byte"

echo "[3/5] count, naming and drawing content"
CONTROLS="$("$PYTHON" -c '
import re, pathlib
root = pathlib.Path("src/widget/capability/properties")
parts = [root / "mod.rs"] + sorted(p for p in root.glob("*.rs") if p.name != "mod.rs")
src = "\n".join(p.read_text(encoding="utf-8") for p in parts)
print(len(re.findall(r"canonical_name:\s*\x22", src)))
')"
# The extra appearances are read from the exporter's own table rather than counted here.
#
# # Why derived and not hard-coded
#
# A number written into this gate would have to be edited in lockstep with `EXTRA_APPEARANCES`,
# and the failure mode of forgetting is the one this check exists to catch — a snapshot file that
# nothing accounts for. Reading the table means "which files exist" and "which states are declared"
# are the same fact, so adding an appearance cannot leave this gate asserting a stale total.
EXTRAS="$("$PYTHON" tools/svg_snapshot_check.py extras)"
# The companion pairings are read from the exporter's own `PAIRS` table for the same reason:
# a pair is two files, and a number written here could drift from the table that declares
# them. A missing pair would otherwise be silently subtracted from an expected total.
PAIRS="$("$PYTHON" tools/svg_snapshot_check.py pairs)"
COMMITTED="$(find "$SNAPSHOT_DIR" -maxdepth 1 -name '*.svg' | wc -l)"
# The icon sheets are counted separately, because they are a different *kind* of file: they
# do not come from the control registry, so folding them into `CONTROLS * 2` would make the
# control count wrong instead of the sheet count. Derived from the files that exist, so a
# missing sheet fails the comparison below rather than being silently subtracted.
SHEETS="$(find "$SNAPSHOT_DIR" -maxdepth 1 -name 'icon_sheet*.svg' | wc -l)"
# An extra appearance is rendered as a **pair**, like a default one.
#
# `EXTRAS * 2` and not `EXTRAS`: the exporter writes each extra under both appearances, because a
# shape reachable only through a factory property needs its own light/dark comparison — the pair on
# the default shape says nothing about, say, `draw_win_panel_frame`'s white/grey bevel, whose whole
# purpose is an illusion of relief and which is only ever reachable by setting the property. A total
# of `EXTRAS` here would have made this gate report every declared extra as an unaccounted file.
EXPECTED=$((CONTROLS * 2 + EXTRAS * 2 + PAIRS * 2 + SHEETS))
if [[ "$COMMITTED" -ne "$EXPECTED" ]]; then
    echo "  FAIL  expected $EXPECTED committed SVGs ($CONTROLS controls x 2 appearances + $EXTRAS extra state(s) x 2 + $PAIRS companion pair(s) x 2 + $SHEETS icon sheet(s)), found $COMMITTED"
    exit 1
fi
echo "  PASS  $CONTROLS controls x 2 appearances + $EXTRAS extra x 2 + $PAIRS pairs x 2 + $SHEETS icon sheet(s) = $COMMITTED files"

echo "[3b/5] every snapshot contains content, not just a skeleton"
EMPTY="$("$PYTHON" tools/svg_snapshot_check.py empty)"
if [[ -n "$EMPTY" ]]; then
    echo "  FAIL  these snapshots are not reviewable:"
    printf '%s\n' "$EMPTY"
    exit 1
fi
echo "  PASS  every snapshot has content (>=3 elements, or a documented shape-only control)"

echo "[4/5] the appearances differ for every control, or the control is recorded as exempt"
SAME="$("$PYTHON" tools/svg_snapshot_check.py same)"
if [[ -n "$SAME" ]]; then
    echo "  FAIL  these controls do not respond to the theme, so their snapshot pair proves nothing:"
    printf '%s\n' "$SAME"
    echo "  If a control is theme-blind on purpose, register it with its reason in"
    echo "  tools/control_color_exemptions.txt; if it is a defect, fix the control."
    exit 1
fi

echo "[5/5] the committed gallery index matches the snapshot set"
# `control.md` is generated from the registry by `tools/generate_control_index.py`, so it is
# a *view* of the snapshots rather than a second copy of them. Its value is exactly that
# property, and it is lost the moment someone edits the page by hand or adds a control
# without regenerating it — the page would then describe a set that no longer exists, which
# is the same "current picture" failure the snapshots themselves are guarded against.
#
# The check regenerates into a scratch file and diffs, so the committed page must equal its
# producer's output byte for byte. Exit 1 with the diff, not with prose: the fix is always
# "run the generator".
GALLERY_SCRATCH="$(mktemp -d 2>/dev/null || mktemp -d -t gallery)"
trap 'rm -rf "$GALLERY_SCRATCH"' EXIT
# The generator writes `control.md` **in place**, so the committed copy has to be preserved
# *before* it runs: comparing afterwards would compare the fresh output with itself and the
# gate would pass over any hand-edit — which is precisely the defect this step exists to
# catch, and the first version of this step had it. `cp` rather than `git show` so the check
# works on a tree whose changes are not yet staged.
cp control.md "$GALLERY_SCRATCH/committed.md"
# `"$PYTHON"`, not a bare `python3`: this file already sources `lib_python.sh` (see the top) exactly
# because `python3` is not a safe name on every host -- on Windows the Store installs an execution
# alias under that name which can *block* on the Store UI instead of running the script, turning a
# check into a hang. This one call site spelled the interpreter directly and so bypassed the helper,
# which made the last step of this gate the single place the resolution did not apply. The failure
# it produced was misleading, too: it reported "the gallery generator itself failed" while the real
# problem was which interpreter was being asked to run it.
if ! "$PYTHON" tools/generate_control_index.py > "$GALLERY_SCRATCH/gen.log" 2>&1; then
    echo "  FAIL  the gallery generator itself failed:"
    sed 's/^/        /' "$GALLERY_SCRATCH/gen.log"
    cp "$GALLERY_SCRATCH/committed.md" control.md
    exit 1
fi
if ! diff -u "$GALLERY_SCRATCH/committed.md" control.md > "$GALLERY_SCRATCH/gallery.diff"; then
    echo "  FAIL  control.md is stale — it does not match what the generator produces now:"
    sed 's/^/        /' "$GALLERY_SCRATCH/gallery.diff" | head -40
    echo "        regenerate with: $PYTHON tools/generate_control_index.py"
    exit 1
fi
echo "  PASS  control.md matches the generated index ($(grep -v 'pair_' control.md | grep -c 'light\.svg) |$') control rows + $(grep -c '^| `pair_' control.md) pair rows)"

echo ""
echo "check_svg_snapshots: checked=$CONTROLS skipped=0 failed=0 (each with a dark and a light snapshot)"
